package cli

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"
	"time"

	core "github.com/nostalume/mountweave"
)

const weiyunOrigin = "https://www.weiyun.com"

var weiyunAuthorization = managedAuthorization{
	provider: "weiyun", label: "Weiyun", method: "browser", staticOnly: true,
	authorize: authorizeWeiyun,
}

func authorizeWeiyun(ctx context.Context, _ oauthClient, _ []string, _ authorizationIntent, out io.Writer) (oauthGrant, error) {
	// Weiyun's short code is a 16-character hex string generated by the client.
	// An exchange before consent returns the same code as an expired session.
	expired := &problem{Code: "interaction_required", Message: "Weiyun authorization timed out.",
		NextAction: "Start authorization again to open a new link."}
	ctx, cancel := context.WithTimeoutCause(ctx, 5*time.Minute, expired)
	defer cancel()
	var nonce [8]byte
	rand.Read(nonce[:])
	code := hex.EncodeToString(nonce[:])
	target := weiyunOrigin + "/authorize/token?code=" + code
	if _, err := fmt.Fprintln(out, "\nWeiyun authorization\n  Weiyun grants permission to operate on all files in your account.\n  This version of mweave uses that access to browse and download files.\n  Approve access in the browser. mweave will continue automatically."); err != nil {
		return oauthGrant{}, err
	}
	launchCtx, stopLaunch := context.WithTimeout(ctx, 5*time.Second)
	launchErr := launchOAuthBrowser(launchCtx, target)
	stopLaunch()
	if err := context.Cause(ctx); err != nil {
		return oauthGrant{}, err
	}
	if launchErr != nil {
		if _, err := fmt.Fprintf(out, "  Open this URL: %s\n", target); err != nil {
			return oauthGrant{}, err
		}
	}
	if _, err := fmt.Fprintln(out, "  Waiting for browser approval (Ctrl+C to cancel)."); err != nil {
		return oauthGrant{}, err
	}
	for {
		if err := context.Cause(ctx); err != nil {
			return oauthGrant{}, err
		}
		req, err := http.NewRequestWithContext(ctx, http.MethodPost, weiyunOrigin+"/api/v3/mcp/token/code", strings.NewReader("{\"code\":\""+code+"\"}"))
		if err != nil {
			return oauthGrant{}, err
		}
		req.Header.Set("Content-Type", "application/json")
		var reply struct {
			Token string      `json:"token"`
			Code  json.Number `json:"code"`
		}
		status, err := readOAuthResponse(req, &reply)
		if cause := context.Cause(ctx); cause != nil {
			return oauthGrant{}, cause
		}
		if err != nil {
			return oauthGrant{}, err
		}
		if status == http.StatusTooManyRequests {
			return oauthGrant{}, core.Fail(core.UpstreamThrottled, nil)
		}
		if status == http.StatusOK && (reply.Code == "" || reply.Code == "0") {
			if reply.Token == "" || strings.ContainsFunc(reply.Token, func(r rune) bool {
				return r < '!' || r > '~' || r == ';'
			}) {
				return oauthGrant{}, core.Fail(core.InvalidUpstreamResponse, nil)
			}
			return oauthGrant{Label: "Weiyun account", Access: reply.Token}, nil
		}
		if reply.Code == "11510" && (status == http.StatusOK || status == http.StatusBadRequest) {
			select {
			case <-ctx.Done():
				return oauthGrant{}, context.Cause(ctx)
			case <-time.After(2 * time.Second):
			}
			continue
		}
		if reply.Code == "117402" || status == http.StatusUnauthorized || status == http.StatusForbidden {
			return oauthGrant{}, &problem{Code: "interaction_required", Message: "Weiyun rejected the authorization.",
				NextAction: "Start a new Weiyun authorization or use a token reference."}
		}
		return oauthGrant{}, core.Fail(core.UpstreamFailure, nil)
	}
}
